  infoBg.on('pointerup',   () => this.showInfoPanel(def));
  const infoLabel = this.add.text(108, BTN_Y, '📋  정보 보기', {
    fontSize: '14px', color: '#cccccc', fontStyle: 'bold',
  }).setOrigin(0.5);
  panel.add(infoBg);
  panel.add(infoLabel);

