/**
 * 스토리 진행도 추적 유틸리티
 *
 * localStorage에 djb2 서명과 함께 저장합니다.
 * 서명 불일치 시 변조로 판단하고 초기값으로 초기화합니다.
 */

const STORAGE_KEY = 'storyProgress';
const SIG_KEY     = 'storyProgressSig';
const _SALT = 'ddong-story-\u0076\u0031';

export interface StoryProgress {
  totalPlaySeconds: number;      // 총 플레이 시간(초) = "달린 거리 m" (score * 0.1)
  chibiPlayCount: number;        // 치비로 플레이 완료 횟수
  totalTopazCollected: number;   // 토파즈 똥 수집 누적
  cumulativeSkorEarned: number;  // 누적 SKOR 획득량
}

const DEFAULT: StoryProgress = {
  totalPlaySeconds: 0,
  chibiPlayCount: 0,
  totalTopazCollected: 0,
  cumulativeSkorEarned: 0,
};

function _sign(p: StoryProgress): string {
  const str = [
    p.totalPlaySeconds,
    p.chibiPlayCount,
    p.totalTopazCollected,
    p.cumulativeSkorEarned,
  ].join(':') + _SALT;
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
  return h.toString(36);
}

export function getStoryProgress(): StoryProgress {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const sig = localStorage.getItem(SIG_KEY);
    if (!raw) return { ...DEFAULT };
    const p = JSON.parse(raw) as StoryProgress;
    if (!sig) {
      // 최초 마이그레이션: 서명 발급
      saveStoryProgress(p);
      return p;
    }
    if (_sign(p) !== sig) {
      // 변조 감지 → 초기화
      saveStoryProgress({ ...DEFAULT });
      return { ...DEFAULT };
    }
    return p;
  } catch {
    return { ...DEFAULT };
  }
}

export function saveStoryProgress(p: StoryProgress): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(p));
  localStorage.setItem(SIG_KEY, _sign(p));
}

/** 게임 종료 시 플레이 시간(초) 누적 */
export function addPlaySeconds(seconds: number): void {
  if (seconds <= 0) return;
  const p = getStoryProgress();
  p.totalPlaySeconds += seconds;
  saveStoryProgress(p);
}

/** 치비로 플레이 완료 시 횟수 +1 */
export function incrementChibiPlayCount(): void {
  const p = getStoryProgress();
  p.chibiPlayCount += 1;
  saveStoryProgress(p);
}

/** 게임 종료 시 토파즈 수집 수 누적 */
export function addTopazCollected(count: number): void {
  if (count <= 0) return;
  const p = getStoryProgress();
  p.totalTopazCollected += count;
  saveStoryProgress(p);
}

/** SKOR 획득 시 누적량 업데이트 */
export function addSkorEarned(amount: number): void {
  if (amount <= 0) return;
  const p = getStoryProgress();
  p.cumulativeSkorEarned += amount;
  saveStoryProgress(p);
}

