input.new_string:
private hideCharacterDetail(): void {
  this.hideLogTerminal();
  this.hideInfoPanel();
  this.detailPanel?.destroy();
  this.detailPanel = null;
}

private hideLogTerminal(): void {
  this.logTerminal?.destroy();
  this.logTerminal = null;
}

private showLogTerminal(): void {
  this.hideLogTerminal();

  const progress = getStoryProgress();
  const TERM_DEPTH = 400;
  const HEADER_H = 52;
  const SCROLL_TOP = HEADER_H;
  const SCROLL_BOTTOM = 600;
  const VISIBLE_H = SCROLL_BOTTOM - SCROLL_TOP;
  const PAD = 18;
  const LINE_H = 20;
  const MONO = '"Courier New", Courier, monospace';
  const GREEN = '#00ff41';
  const DIM   = '#336633';
  const LOCK  = '#444444';

  const terminal = this.add.container(0, 0).setDepth(TERM_DEPTH);
  this.logTerminal = terminal;

  // 전체 배경
  terminal.add(this.add.rectangle(200, 300, 400, 600, 0x000000, 0.97).setInteractive());

  // ── 헤더 ──────────────────────────────────────────────────────────
  terminal.add(this.add.rectangle(200, HEADER_H / 2, 400, HEADER_H, 0x001400));
  terminal.add(this.add.rectangle(200, HEADER_H, 400, 1, 0x00ff41, 1));
  terminal.add(this.add.text(PAD, HEADER_H / 2, '>_ ROUTE LOG TERMINAL', {
    fontSize: '14px', color: GREEN, fontFamily: MONO, fontStyle: 'bold',
  }).setOrigin(0, 0.5));

  // ✕ 닫기
  const closeBg = this.add.rectangle(378, HEADER_H / 2, 36, 36, 0x000000, 0)
    .setInteractive({ useHandCursor: true });
  const closeTxt = this.add.text(378, HEADER_H / 2, '✕', {
    fontSize: '16px', color: DIM, fontFamily: MONO,
  }).setOrigin(0.5);
  closeBg.on('pointerover', () => closeTxt.setColor(GREEN));
  closeBg.on('pointerout',  () => closeTxt.setColor(DIM));
  closeBg.on('pointerup',   () => this.hideLogTerminal());
  terminal.add(closeBg);
  terminal.add(closeTxt);

  // ── 스크롤 컨텐츠 빌드 ────────────────────────────────────────────
  const content = this.add.container(0, SCROLL_TOP);
  terminal.add(content);

  let curY = PAD;

  for (const log of STORY_LOGS) {
    const unlocked = isLogUnlocked(log.id, progress);
    const idStr = `#${String(log.id).padStart(3, '0')}`;

    if (unlocked) {
      // 잠금 해제: 전체 내용 표시
      const titleTxt = this.add.text(PAD, curY, `▌ LOG ${idStr}`, {
        fontSize: '13px', color: GREEN, fontFamily: MONO, fontStyle: 'bold',
      });
      content.add(titleTxt);
      curY += LINE_H + 4;

      const bodyTxt = this.add.text(PAD + 8, curY, log.content, {
        fontSize: '12px', color: '#aaffaa', fontFamily: MONO,
        wordWrap: { width: 400 - PAD * 2 - 8 },
        lineSpacing: 4,
      });
      content.add(bodyTxt);
      curY += bodyTxt.height + 20;
    } else {
      // 잠금: 조건만 표시
      const titleTxt = this.add.text(PAD, curY, `▌ LOG ${idStr}  [LOCKED]`, {
        fontSize: '13px', color: LOCK, fontFamily: MONO,
      });
      content.add(titleTxt);
      curY += LINE_H + 2;

      const hintTxt = this.add.text(PAD + 8, curY, `> ${log.unlockHint}`, {
        fontSize: '11px', color: LOCK, fontFamily: MONO,
      });
      content.add(hintTxt);
      curY += LINE_H + 14;
    }

    // 구분선
    const divider = this.add.graphics();
    divider.lineStyle(1, 0x003300, 1);
    divider.lineBetween(PAD, curY, 400 - PAD, curY);
    content.add(divider);
    curY += 12;
  }

  const totalH = curY + PAD;
  this.termScrollOffset = 0;
  this.termMaxScroll = Math.max(0, totalH - VISIBLE_H);
  this.termHasDragged = false;

  // 스크롤 마스크
  const maskGfx = this.make.graphics({ x: 0, y: 0 });
  maskGfx.fillRect(0, SCROLL_TOP, 400, VISIBLE_H);
  content.setMask(maskGfx.createGeometryMask());

  // 드래그 스크롤
  const updateScroll = () => {
    content.y = SCROLL_TOP - this.termScrollOffset;
  };

  terminal.on('destroyed', () => {
    this.input.off('pointerdown', onDown);
    this.input.off('pointermove', onMove);
    this.input.off('pointerup', onUp);
    maskGfx.destroy();
  });

  const onDown = (p: Phaser.Input.Pointer) => {
    if (!this.logTerminal) return;
    if (p.y < SCROLL_TOP) return;
    this.termPointerDownY = p.y;
    this.termPointerDownScrollY = this.termScrollOffset;
    this.termHasDragged = false;
  };
  const onMove = (p: Phaser.Input.Pointer) => {
    if (!this.logTerminal || !p.isDown || p.y < SCROLL_TOP) return;
    const dy = this.termPointerDownY - p.y;
    if (Math.abs(dy) > 5) this.termHasDragged = true;
    this.termScrollOffset = Phaser.Math.Clamp(
      this.termPointerDownScrollY + dy, 0, this.termMaxScroll
    );
    updateScroll();
  };
  const onUp = () => {
    if (!this.logTerminal) return;
    this.time.delayedCall(0, () => { this.termHasDragged = false; });
  };

  this.input.on('pointerdown', onDown);
  this.input.on('pointermove', onMove);
  this.input.on('pointerup', onUp);
}

